from pathlib import Path
import re
root = Path('.')
p = root / 'assets/portfolio-interactions.js'
s = p.read_text()
def one(old, new):
    global s
    assert s.count(old) == 1, (old[:80], s.count(old))
    s = s.replace(old, new, 1)
start = s.index('    const css = `')
end = s.index('`;\n    function mount()', start)
s = s[:start] + '''    // Single owner of carousel layout. Credential content is real DOM from certs.js,
    // never generated by URL-dependent CSS pseudo-elements in the export chunks.
    const css = `
.hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(25rem,.95fr);column-gap:clamp(2rem,5vw,4rem);align-items:center}
.hero>.role,.hero>h1,.hero>.trust-statement,.hero>.hero-copy,.hero>.proof-links{grid-column:1}
.credential-carousel{display:flex;flex-direction:column;grid-column:2;grid-row:1/7;width:100%;max-width:38rem;min-width:0;justify-self:end}
/* Overlaid grid items share the tallest card's intrinsic height, including when
   inactive. Long titles, descriptions and zoom never collide with the footer. */
.credential-carousel-stage{order:0;flex:none;display:grid;grid-template-columns:minmax(0,1fr);position:relative;min-height:15rem;padding:1.1rem 0;overflow:hidden}
.credential-carousel-card{grid-area:1/1;position:relative;left:0;z-index:0;justify-self:center;align-self:stretch;display:flex;flex-direction:column;gap:.5rem;width:min(70%,18rem);min-width:0;min-height:12.75rem;padding:1rem 1.15rem;border:2px solid var(--line);background:var(--paper);color:var(--ink);opacity:0;transform:scale(.68);pointer-events:none;text-decoration:none;transition:left 400ms ease,opacity 400ms ease,transform 400ms ease,border-color 400ms ease}
.credential-carousel-card[data-position="current"]{left:0;z-index:3;border-color:var(--black);box-shadow:4px 4px 0 var(--soft);opacity:1;transform:scale(1);pointer-events:auto}
.credential-carousel-card[data-position="previous"]{left:-32%;z-index:2;opacity:.46;transform:translateY(.6rem) scale(.78);pointer-events:auto;cursor:pointer}
.credential-carousel-card[data-position="next"]{left:32%;z-index:2;opacity:.46;transform:translateY(.6rem) scale(.78);pointer-events:auto;cursor:pointer}
.credential-carousel-card[data-position="past"]{left:-62%;opacity:0;transform:translateY(.8rem) scale(.68)}
.credential-carousel-card[data-position="future"]{left:62%;opacity:0;transform:translateY(.8rem) scale(.68)}
.credential-carousel-head{display:flex;align-items:center;justify-content:space-between;gap:.5rem;min-width:0;min-height:1.25rem}
.credential-carousel-kicker,.credential-carousel-company,.credential-carousel-meta,.credential-carousel-verify{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.credential-carousel-kicker{color:var(--muted);font-size:10px;font-weight:700;line-height:1.3;letter-spacing:.12em;text-transform:uppercase}
.credential-carousel-company{flex:none;display:inline-flex;align-items:center;justify-content:center;min-height:1.15rem;padding:.14rem .34rem;border:1px solid var(--line);font-size:9px;font-weight:700;line-height:1.1;white-space:nowrap}
.credential-carousel-card[data-position="current"] .credential-carousel-company{border-color:var(--black)}
.credential-carousel-title{margin:0;font-size:clamp(26px,3vw,32px);line-height:1.06;letter-spacing:-.025em;overflow-wrap:anywhere}
.credential-carousel-card.has-long-title .credential-carousel-title{font-size:clamp(21px,2vw,25px);line-height:1.08;letter-spacing:-.02em}
.credential-carousel-description{font-size:12px;line-height:1.4;color:var(--muted);overflow-wrap:break-word}
.credential-carousel-footer{display:flex;flex-wrap:wrap;align-items:center;gap:.15rem .5rem;margin-top:auto;padding-top:.35rem}
.credential-carousel-meta{display:inline-flex;align-items:center;gap:.3em;color:var(--muted);font-size:11px;line-height:1.4;white-space:nowrap}
.credential-carousel-verify{display:inline-flex;align-items:center;min-height:24px;margin-left:auto;color:var(--ink);font-size:11px;line-height:1.2;text-decoration:underline;text-underline-offset:.18em;white-space:nowrap;cursor:pointer}
/* Reserve the same footer space while keeping inactive verification links out
   of pointer interaction, the accessibility tree, and the tab sequence. */
.credential-carousel-verify[hidden]{display:inline-flex;visibility:hidden;pointer-events:none}
.credential-carousel-controls{order:1;display:grid;grid-template-columns:44px minmax(0,1fr) 44px;gap:.25rem;align-items:center;width:min(100%,30rem);margin:.1rem auto 0}
.credential-carousel-arrow,.credential-carousel-dot{font:inherit;cursor:pointer}.credential-carousel-arrow{min-width:44px;min-height:44px;padding:0;border:0;background:transparent;color:var(--ink);opacity:0;pointer-events:none;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:20px}
.credential-carousel:hover .credential-carousel-arrow,.credential-carousel:focus-within .credential-carousel-arrow{opacity:1;pointer-events:auto}
.credential-carousel-dots{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:0 .05rem}.credential-carousel-dot{position:relative;width:18px;min-height:36px;padding:0;border:0;background:transparent}
.credential-carousel-dot::before{position:absolute;top:50%;left:50%;width:6px;height:6px;background:var(--line);clip-path:circle(50%);content:"";transform:translate(-50%,-50%)}.credential-carousel-dot.is-active::before{background:var(--black)}
@media (hover:none){.credential-carousel-arrow{opacity:1;pointer-events:auto}}@media (prefers-reduced-motion:reduce){.credential-carousel-card{transition:none}}
@media (max-width:880px){.hero{grid-template-columns:1fr;column-gap:0}.credential-carousel{grid-column:1;grid-row:auto;max-width:36rem;justify-self:center;margin-top:1.75rem}}
@media (max-width:640px){.credential-carousel{margin-top:1.25rem}.credential-carousel-card{width:min(78%,17.5rem);padding:.85rem .9rem}.credential-carousel-card[data-position="previous"]{left:-41%}.credential-carousel-card[data-position="next"]{left:41%}.credential-carousel-card[data-position="past"]{left:-74%}.credential-carousel-card[data-position="future"]{left:74%}.credential-carousel-title{font-size:clamp(24px,7vw,30px)}.credential-carousel-card.has-long-title .credential-carousel-title{font-size:clamp(21px,6vw,24px)}.credential-carousel-controls{width:100%}.credential-carousel-dot{width:16px;min-height:32px}.credential-carousel-arrow{opacity:1;pointer-events:auto}}
''' + s[end:]
one('        category: cert.category,', '        category: cert.category,\n        description: cert.description,')
one('        title.textContent = item.title;', '''        title.textContent = item.title;
        const description = document.createElement("span");
        description.className = "credential-carousel-description";
        description.textContent = item.description;
        const footer = document.createElement("div");
        footer.className = "credential-carousel-footer";
        const metadata = document.createElement("span");
        metadata.className = "credential-carousel-meta";''')
one('        verify.className = "credential-carousel-verify";', '''        verify.className = "credential-carousel-verify";
        verify.textContent = "Verified ↗";''')
one('        card.append(head, title, issuer, issued, verify);', '''        metadata.append(issuer, document.createTextNode("·"), issued);
        footer.append(metadata, verify);
        card.append(head, title, description, footer);''')
one('            verify.textContent = "Verified ↗";\n', '')
one('            verify.textContent = "";\n', '')
one('        stage.setPointerCapture?.(pointerId);\n', '''        // Capture only after an actual drag. Capturing on pointerdown retargets
        // an ordinary side-card click to the stage and prevents selection.
''')
one('        dragging = true;\n        event.preventDefault();', '''        if (!dragging) stage.setPointerCapture?.(pointerId);
        dragging = true;
        event.preventDefault();''')
one('      stage.addEventListener("pointerup", (event) => finish(event));', '      window.addEventListener("pointerup", (event) => finish(event));')
one('      stage.addEventListener("pointercancel", (event) => finish(event, true));', '      window.addEventListener("pointercancel", (event) => finish(event, true));')
p.write_text(s)
p = root / '_next/static/chunks/03~_g8i41_-g_.css'
p.write_text('@import url("./03~_g8i41_-g_-base.css");\n/* Carousel styles are owned by assets/portfolio-interactions.js. */\n')
p = root / '_next/static/chunks/03~_g8i41_-g_-base.css'
s = p.read_text()
marker = '\n#m3ez-credential-carousel-v1 .credential-carousel-card'
assert marker in s
s = s.split(marker, 1)[0] + '\n'
