p.write_text('\n'.join('  assert.doesNotMatch(css, /#m3ez-credential-carousel-v1 \\.credential-carousel-(?:stage|card)\\{/);' if '#m3ez-credential-carousel-v1' in line else line for line in lines) + '\n')
p = root / 'tests/browser/layout-readability.test.mjs'
s = "import { certs } from '../../assets/certs.js';\n" + p.read_text()
s = s.replace("await page.locator('.credential-grid-item').count(), 13", "await page.locator('.credential-grid-item').count(), certs.length")
s = s.replace("page.locator(currentCard).getAttribute('href')", "page.locator(currentCard).locator('.credential-carousel-verify').getAttribute('href')")
s = s.replace("document.activeElement.matches('.credential-carousel-card')", "document.activeElement.matches('.credential-carousel-card[data-position=\"current\"] .credential-carousel-verify')")
p.write_text(s)
# Remove the one-time mutation steps before the tested snapshot is committed.
p = root / '.github/workflows/carousel-regression.yml'
s = p.read_text().replace('  contents: write', '  contents: read')
s = re.sub(r'      - name: Apply reviewed candidate\n.*?(?=      - name: Source tests)', '', s, flags=re.S)
s = re.sub(r'      - name: Record tested branch snapshot\n.*?(?=      - name: Export verification source)', '', s, flags=re.S)
p.write_text(s)
Path(__file__).unlink()
